import { readFileSync, writeFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";

export async function gate({ referenceDir, submissionDir }) {
  const submissionPath = path.join(submissionDir, "answer.mjs");
  const pinnedPath = path.join(referenceDir, "pinned-test-cases.txt");
  let pinnedSrc;
  try {
    pinnedSrc = readFileSync(pinnedPath, "utf8");
  } catch (e) {
    return { accept: false, reason: "Could not read pinned test cases: " + e.message };
  }

  const extraTests = `
test("extra: large all-same array", () => {
  const arr = new Array(200).fill(7);
  assert.deepStrictEqual(dedupeSorted(arr), [7]);
});
test("extra: does not mutate input array", () => {
  const arr = [1, 1, 2, 2, 3];
  const copy = arr.slice();
  dedupeSorted(arr);
  assert.deepStrictEqual(arr, copy);
});
test("extra: result is an array", () => {
  const result = dedupeSorted([1, 2, 3]);
  assert.ok(Array.isArray(result));
});
test("extra: long run with many consecutive duplicates", () => {
  const arr = [];
  const expected = [];
  for (let i = -50; i <= 50; i++) { arr.push(i, i, i); expected.push(i); }
  assert.deepStrictEqual(dedupeSorted(arr), expected);
});
test("extra: single duplicate pair only", () => {
  assert.deepStrictEqual(dedupeSorted([2, 2]), [2]);
});
test("extra: two elements distinct", () => {
  assert.deepStrictEqual(dedupeSorted([1, 2]), [1, 2]);
});
test("extra: fresh randomized property check, wider range", () => {
  for (let trial = 0; trial < 30; trial++) {
    const len = Math.floor(Math.random() * 15);
    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 9) - 4).sort((a, b) => a - b);
    const expected = [...new Set(arr)];
    assert.deepStrictEqual(dedupeSorted(arr), expected);
  }
});
`;

  const harnessSrc =
    'import test from "node:test";\n' +
    'import assert from "node:assert/strict";\n' +
    'import { dedupeSorted } from ' + JSON.stringify(submissionPath) + ';\n\n' +
    pinnedSrc + '\n' + extraTests;

  const harnessPath = path.join(referenceDir, "harness.mjs");
  writeFileSync(harnessPath, harnessSrc);

  const result = spawnSync(process.execPath, ["--test", harnessPath], {
    encoding: "utf8",
    timeout: 15000,
    maxBuffer: 10 * 1024 * 1024,
  });

  if (result.error) {
    return { accept: false, reason: "Failed to execute test harness: " + result.error.message };
  }

  const output = (result.stdout || "") + (result.stderr || "");

  if (result.signal) {
    return { accept: false, reason: "Test harness terminated by signal " + result.signal + " (likely timeout or infinite loop):\n" + output.slice(0, 2000) };
  }

  if (result.status === 0) {
    return { accept: true, reason: "All pinned test cases and additional adversarial checks passed." };
  }

  return { accept: false, reason: "Pinned/extra test suite failed (exit code " + result.status + "):\n" + output.slice(0, 4000) };
}

